mapper.select:
select t1.id as id, t1.material_code as materialCode, t1.tobacco_year as tobaccoYear, t1.stack_name as stackName, t1.maintence_style as maintenceStyle, t2.phases as phases, t2.id as stageId, t2.created_time as createdTime from tb_maintain_plan t1 left join tb_maintain_plan_stage t2 on t1.stage_id = t2.id
t1.is_end = '0'
and t1.material_code like concat('%',#{maintainPlanDto.materialCode},'%')
and t1.tobacco_year like concat('%',#{maintainPlanDto.tobaccoYear},'%')
and t1.stack_name like concat('%',#{maintainPlanDto.stackName},'%')
and t2.created_time >= #{maintainPlanDto.startTime}
and t2.created_time <= #{maintainPlanDto.endTime}
and t2.phases = #{maintainPlanDto.phases}
and t1.maintence_style = #{maintainPlanDto.maintenceStyle}
order by created_time desc

mapper.update:
update tb_maintain_plan

    principal_name = #{maintainPlanDto.name},
    principal_ids = #{maintainPlanDto.principalId}

where id = #{maintainPlanDto.id}

update tb_maintain_plan_stage
maintain_days = #{maintainPlanDto.maintainDays}, aftercare_date_start = #{maintainPlanDto.aftercareDateStart}, aftercare_date_end = #{maintainPlanDto.aftercareDateEnd}, maintain_count = #{maintainPlanDto.maintainCount}, oxygen_reduction_time = #{maintainPlanDto.oxygenReductionTime}, expire_time = #{maintainPlanDto.expireTime}, update_user = #{maintainPlanDto.updateUser}, updated_time = #{maintainPlanDto.updatedTime}
where id = #{maintainPlanDto.stageId}

mapper.select:
select alarm_value_setting_id from tb_maintain_plan_stage
WHERE maintain_plan_id in

    #{id}

SELECT
t1.id AS id,
t1.material_code AS materialCode,
t2.maintain_count AS maintainCount,
t1.maintence_style AS maintenceStyle,
t2.phases AS phases,
t1.stack_name AS stackName,
t2.maintain_days AS maintainDays,
t2.alarm_value_setting_id as alarmValueSettingId,
t2.is_change AS changeStatus,
created_time AS createdTime
FROM tb_maintain_plan t1
LEFT JOIN tb_maintain_plan_stage t2 ON t1.id = t2.maintain_plan_id
WHERE
t1.id  = #{maintainPlanDto.id}
and t2.version = #{maintainPlanDto.version}
 and t1.stack_id = #{maintainPlanDto.stackId}
 and t2.phases = #{maintainPlanDto.phases}
 and t1.maintence_style = #{maintainPlanDto.maintenceStyle}
 and t2.is_change=#{maintainPlanDto.changeStatus}
 and t1.material_code like concat('%',#{maintainPlanDto.materialCode},'%')
 and t2.maintain_count = #{maintainPlanDto.maintainCount}
and t2.updated_time >= #{maintainPlanDto.startTime}
and t2.updated_time <= #{maintainPlanDto.endTime}
order by is_change
